var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if(scene.name!="BlackHoleStationEcologicalParkV017"||UnityEditor.EditorApplication.isPlaying)throw new System.Exception("V017 Edit required");
var garden=UnityEngine.GameObject.Find("V015 package - glass ecology garden").transform;
bool Roof(UnityEngine.Transform t)=>t.name.IndexOf("roof",System.StringComparison.OrdinalIgnoreCase)>=0||t.name.Contains("顶棚")||t.name.StartsWith("Solid portal canopy")||t.name=="Silver combined framing"||t.name=="South garden continuous entry canopy";
var removed=new System.Collections.Generic.List<object>();
foreach(var t in garden.GetComponentsInChildren<UnityEngine.Transform>(true).Where(Roof)){
 if(!t.gameObject.activeSelf)continue;
 UnityEditor.Undo.RecordObject(t.gameObject,"Remove park roofs at user request");
 removed.Add(new{name=t.name,path=UnityEditor.AnimationUtility.CalculateTransformPath(t,garden),wasVisible=t.gameObject.activeInHierarchy,meshes=t.GetComponentsInChildren<UnityEngine.MeshRenderer>().Length});
 t.gameObject.SetActive(false);
}
UnityEngine.Physics.SyncTransforms();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);
var remaining=garden.GetComponentsInChildren<UnityEngine.MeshRenderer>().Where(r=>Roof(r.transform)).Select(r=>r.name).ToArray();
var report=new{scene=scene.path,removed,remainingRoofMeshes=remaining,outerDoors=garden.GetComponentsInChildren<QuQu.StationConservatoryDoor>().Length,careAirlocks=garden.GetComponentsInChildren<QuQu.StationPressureVestibule>().Select(v=>v.StableId).ToArray(),userDirection="Open-air main park with no roof; original source scene and functional objects preserved"};
System.IO.Directory.CreateDirectory("../docs/validation/station-v017-open-park-20261003");
System.IO.File.WriteAllText("../docs/validation/station-v017-open-park-20261003/roof-removal.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));
return new{removed=removed.Count,remainingRoofMeshes=remaining,report.outerDoors,report.careAirlocks};
